const { useState } = React;

function Choice() {
  const [selected, setSelected] = useState(false);
  console.log('렌더:', selected);

  function handleClick() {
    console.log('이벤트 처리');
    setSelected(true);
  }

  return (
    <button type="button" onClick={handleClick}>
      {selected ? '선택됨' : '선택하기'}
    </button>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Choice />);

